# ---------------- helpers ----------------
def R(n): return M(num(n) if F(n).denominator == 1 else num(float(n), 2)) + ' ៛'
def Rn(n): return M(num(int(n)) if F(n).denominator == 1 else num(float(n), 2))
def D_(n): return M(num(int(n))) + ' \\$'.replace('\\$', '$') if False else M(num(int(n)) + '\\,\\$')
def pct(x, nd=2):
    x = F(x)
    s = f'{float(x):.{nd}f}'.rstrip('0').rstrip('.')
    return s + '\\%'
def Mp(x, nd=2): return M(pct(x, nd))
def distinct(ans, cand, fmt, k=3):
    out = []
    for c in cand:
        c = F(c)
        if c != F(ans) and c > 0 and c not in out: out.append(c)
    d = 2
    while len(out) < k:
        c = F(ans) * (100 + 7 * d) / 100; d += 1
        if c != F(ans) and c not in out: out.append(c)
    return [fmt(c) for c in out[:k]]
def Wr_(ans, cand): return distinct(ans, cand, R)
def Wp(ans, cand): return distinct(ans, cand, lambda v: Mp(v))
def Wn(ans, cand, f=None): return distinct(ans, cand, f or (lambda v: M(num(int(v)) if v.denominator == 1 else frac(v))))

# ---------------- figures (SVG stored in the images table) ----------------
def _txt(x, y, s, anchor='middle', extra=''):
    if extra: st = "font-family='Khmer OS Battambang,Noto Sans Khmer,serif' font-style='normal' font-size='14'"
    else: st = "font-family='Times New Roman,serif' font-style='italic' font-size='13'"
    return f"<text x='{x}' y='{y}' text-anchor='{anchor}' {st} fill='#111'>{s}</text>"
def svg(w, h, body):
    return (f"<svg xmlns='http://www.w3.org/2000/svg' width='{w}' height='{h}' viewBox='0 0 {w} {h}'>"
            f"<rect width='{w}' height='{h}' fill='white'/>{body}</svg>")
def rect_fig(items, unit='cm', title=True):
    """items: (width, height, label_w, label_h, name) drawn to scale k*dim, left to right, bottom aligned."""
    k = max(22 / min(min(i[0], i[1]) for i in items), 0)
    k = min(k, 200 / max(max(i[0], i[1]) for i in items))
    x = 14; body = ''; H = int(max(i[1] for i in items) * k) + 60; base = H - 28
    for (w, h, lw, lh, name) in items:
        pw, ph = w * k, h * k
        body += f"<rect x='{x}' y='{base - ph}' width='{pw}' height='{ph}' fill='#eef3ff' stroke='#1d2540' stroke-width='1.6'/>"
        body += _txt(x + pw / 2, base + 16, lw)
        body += _txt(x + pw + 6, base - ph / 2 + 4, lh, 'start')
        if title and name:
            kh = 'kh'
            body += _txt(x + pw / 2, base + 21, name, extra=kh) if not lw else _txt(x + pw / 2, base - ph / 2 + 4, name, extra=kh)
        x += pw + 52
    return svg(int(x), H, body)
